\title{Transreal Arithmetic, Deepened:\\ Surviving Structure, Homomorphisms,
and the Geometry of a Total Number System}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\maketitle

\begin{abstract}
The \emph{transreal numbers} $\T = \R \cup \{+\infty, -\infty, \Phinull\}$ extend
the real line with two infinities and a value $\Phinull$ (\emph{nullity},
morally $0/0$) so as to make addition, multiplication, negation, and reciprocal
\emph{total}: every operation returns a value for every input, division by zero
included. Totality is bought at a price, and this paper determines that price
exactly. We show the surviving algebraic structure is precisely a pair of
commutative monoids: $(\T, +, 0)$ and $(\T, \cdot, 1)$ are both commutative
monoids, while the ring axioms fail. We prove negation is a homomorphism of both
monoids and an involution, and that $\R$ embeds as a sub-monoid under both
operations. We pin down the exact failures of the multiplicative involution:
reciprocation is self-inverse everywhere except at the single point $-\infty$,
and it commutes with negation everywhere except at $0$, where a signed-zero
phenomenon forces $1/(-0) = +\infty \neq -\infty = -(1/0)$. Finally we equip $\T$
with a natural partial order in which $-\infty < r < +\infty$ for every real $r$
while $\Phinull$ is incomparable to everything; the order is provably not total,
$\R$ order-embeds, and---because $\Phinull$ floats free---$\T$ has neither a
greatest nor a least element, in sharp contrast to the extended reals
$[-\infty, +\infty]$. The recurring theme is \emph{localization of failure}: each
classical law that breaks, breaks at a single explicitly identified point.
\end{abstract}

\section{Introduction}

The prohibition on division by zero is load-bearing: assigning $1/0$ any real
value $c$ forces $1 = 0 \cdot c = 0$, collapsing the field. Yet in computation
the prohibition is a nuisance: any long chain of operations may attempt a
forbidden division, and a program cannot answer ``undefined''; it must return a
value or halt. Floating-point arithmetic addresses this with $\pm\infty$ and
\texttt{NaN}.

\emph{Transreal arithmetic} (Anderson's total arithmetic) is a mathematical
system in this spirit. It enlarges $\R$ with $+\infty$, $-\infty$, and a single
indeterminate value $\Phinull$ (\emph{nullity}), and specifies total rules for
addition, multiplication, negation, and reciprocal. Nullity plays the role of
\texttt{NaN}: it is the value of indeterminate forms ($0/0$, $\infty-\infty$,
$0\cdot\infty$) and is \emph{absorbing}.

Our purpose is to \emph{measure} the system. Which theorems of ordinary
arithmetic and order survive, and which collapse? We give a sharp answer,
organized around \textbf{localization of failure}: every classical law that
fails does so at one explicitly identifiable point.

\paragraph{Contributions.}
\begin{enumerate}[leftmargin=*]
  \item Surviving structure (\S3): $(\T, +, 0)$ and $(\T, \cdot, 1)$ are
  commutative monoids; the ring structure fails via inverses at $+\infty$ and
  distributivity.
  \item Negation as a double homomorphism and involution (\S4).
  \item Faithful embedding of $\R$ as a sub-monoid under both operations (\S4).
  \item Exact reach of the reciprocal involution (\S5): $1/(1/x)=x \iff x \neq
  -\infty$; and $1/(-x) = -(1/x) \iff x \neq 0$.
  \item A non-linear order geometry (\S6): partial, not total; $\R$
  order-embeds; no greatest and no least element.
\end{enumerate}

\section{The transreal numbers}

\begin{definition}[Transreal numbers]
$\T = \R \cup \{+\infty,\ -\infty,\ \Phinull\}$, the disjoint union of a copy of
$\R$ with three new symbols: $+\infty$, $-\infty$, and \emph{nullity}
$\Phinull$. Write $\iota:\R\to\T$ for the inclusion and identify $a$ with
$\iota(a)$ when convenient; $0 = \iota(0)$, $1 = \iota(1)$.
\end{definition}

The governing principle for $\Phinull$ is \textbf{absorption}: nullity is the
value of every indeterminate form and cannot be undone.

\begin{definition}[Addition]
Finite addition is ordinary, $\iota(a)+\iota(b)=\iota(a+b)$; an infinity
dominates a finite summand; $(+\infty)+(-\infty) = \Phinull$; and $\Phinull$
absorbs, $\Phinull + x = x + \Phinull = \Phinull$.
\end{definition}

\begin{definition}[Multiplication]
Finite multiplication is ordinary; $\Phinull$ absorbs; the infinities multiply by
the sign rule, $(+\infty)(+\infty) = (-\infty)(-\infty) = +\infty$ and
$(+\infty)(-\infty) = -\infty$; and for a real $a$,
\[
\iota(a)\cdot(+\infty) =
\begin{cases}+\infty & a>0\\ \Phinull & a=0\\ -\infty & a<0\end{cases}
\qquad
\iota(a)\cdot(-\infty) =
\begin{cases}-\infty & a>0\\ \Phinull & a=0\\ +\infty & a<0\end{cases}
\]
symmetrically in the arguments. The critical clause is $0\cdot(\pm\infty) =
\Phinull$.
\end{definition}

\begin{definition}[Negation]
$-\iota(a) = \iota(-a)$, $-(+\infty)=-\infty$, $-(-\infty)=+\infty$,
$-\Phinull = \Phinull$.
\end{definition}

\begin{definition}[Reciprocal]
\[
\frac{1}{\iota(a)} =
\begin{cases}\iota(a^{-1}) & a\neq 0\\ +\infty & a=0\end{cases}
\qquad \frac{1}{+\infty} = \frac{1}{-\infty} = 0, \qquad
\frac{1}{\Phinull} = \Phinull.
\]
Division $x/y = x\cdot(1/y)$ is total; $0/0 = 0\cdot(+\infty) = \Phinull$.
\end{definition}

\begin{lemma}[Six-way case split]\label{lem:cases6}
Every $t\in\T$ satisfies exactly one of: $t=\Phinull$; $t=+\infty$;
$t=-\infty$; $t=\iota(r)$ with $r>0$; $t=\iota(0)$; $t=\iota(r)$ with $r<0$.
\end{lemma}
\begin{proof}
Immediate from the definition of $\T$ and trichotomy on a real value.
\end{proof}

This split reduces multiplicative associativity to a finite verification: with
three factors, all $6^3 = 216$ sign-configurations agree under both groupings.

\section{Surviving algebraic structure}

\begin{theorem}[Additive commutative monoid]\label{thm:addmon}
$(\T, +, 0)$ is a commutative monoid: $x+y=y+x$, $(x+y)+z=x+(y+z)$, and
$0+x=x=x+0$ for all $x,y,z\in\T$.
\end{theorem}
\begin{proof}[Proof sketch]
Commutativity and associativity are checked on the constructor cases; on the
finite part they reduce to the real identities, and on the singular values they
follow from absorption of $\Phinull$ and the finite-vs-infinite clauses. The
identity law holds because $0$ is a finite real.
\end{proof}

\begin{remark}[No additive group]\label{rem:nogroup}
$+\infty$ has no additive inverse: $(+\infty)+y \in \{+\infty, \Phinull\}$ for
every $y$, never $0$. The loss is localized to the infinities; on $\R$ additive
inverses persist.
\end{remark}

\begin{theorem}[Multiplicative commutative monoid]\label{thm:mulmon}
$(\T, \cdot, 1)$ is a commutative monoid: $x\cdot y = y\cdot x$,
$(x\cdot y)\cdot z = x\cdot(y\cdot z)$, and $1\cdot x = x = x\cdot 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Commutativity follows from symmetry of the definition. Associativity is
Lemma~\ref{lem:cases6} on all three factors, using
$\sgn(ab)=\sgn(a)\sgn(b)$ and absorption. The identity law holds because $1$ is a
nonzero positive real.
\end{proof}

\begin{proposition}[Failure of the ring axioms]\label{prop:noring}
$(\T,+,\cdot,0,1)$ is not a ring:
\begin{enumerate}[leftmargin=*]
  \item No additive inverses (Remark~\ref{rem:nogroup}).
  \item Distributivity fails: e.g.\ $(+\infty)\cdot(1+0)=+\infty$ but
  $(+\infty)\cdot 1 + (+\infty)\cdot 0 = (+\infty) + \Phinull = \Phinull$, and
  $+\infty \neq \Phinull$.
\end{enumerate}
Thus the maximal surviving algebraic structure is exactly the two commutative
monoids of Theorems~\ref{thm:addmon} and~\ref{thm:mulmon}.
\end{proposition}

\section{Negation and the embedding of the reals}

\begin{theorem}[Negation is a bi-homomorphism and involution]\label{thm:neg}
For all $x,y\in\T$: $-(x+y)=(-x)+(-y)$, $-(x\cdot y)=(-x)\cdot y = x\cdot(-y)$,
$(-x)\cdot(-y)=x\cdot y$, and $-(-x)=x$.
\end{theorem}
\begin{proof}[Proof sketch]
Verified on the six-way split. Negation swaps $+\infty\leftrightarrow-\infty$,
fixes $\Phinull$, and negates reals; each clause of the definitions is preserved
by the induced sign flip. The involution holds because $a\mapsto -a$ and the
infinity-swap are each self-inverse.
\end{proof}

\begin{theorem}[Faithful monoid embeddings of $\R$]\label{thm:embed}
The inclusion $\iota:\R\to\T$ is an injective homomorphism of additive monoids
($\iota(a+b)=\iota(a)+\iota(b)$, $\iota(0)=0$) and of multiplicative monoids
($\iota(ab)=\iota(a)\cdot\iota(b)$, $\iota(1)=1$). Hence $\R$ is a
sub-commutative-monoid of $\T$ under each operation.
\end{theorem}
\begin{proof}[Proof sketch]
On finite inputs the operations reduce to real arithmetic; injectivity is
injectivity of the constructor; the unit conditions are the definitions of $0$
and $1$.
\end{proof}

\begin{corollary}
Every polynomial identity valid in $\R$ remains valid in $\T$ provided every
intermediate value is finite. The novelty of $\T$ is concentrated at the singular
values.
\end{corollary}

\section{The reciprocal: exact reach of the involution}

\begin{theorem}[Exact reach of the reciprocal involution]\label{thm:recip}
For all $x\in\T$, $\displaystyle \frac{1}{\,1/x\,} = x \iff x \neq -\infty.$
\end{theorem}
\begin{proof}
On the cases: for nonzero reals $1/(1/x)=x$; for $x=0$, $1/0=+\infty$ and
$1/(+\infty)=0$; for $x=+\infty$, $1/(+\infty)=0$ and $1/0=+\infty$; for
$\Phinull$, both steps give $\Phinull$. For $x=-\infty$: $1/(-\infty)=0$ and
$1/0=+\infty\neq-\infty$. Hence the identity holds except at $-\infty$.
\end{proof}

\begin{remark}
Both infinities have reciprocal $0$, so $0$ cannot record its origin; the tie is
broken by $1/0=+\infty$. This is the entire obstruction: the involution is
repaired on $\T\setminus\{-\infty\}$.
\end{remark}

\begin{theorem}[Reciprocal commutes with negation off zero]\label{thm:recipneg}
For all $x\in\T$ with $x\neq 0$, $\displaystyle \frac{1}{-x} = -\frac{1}{x}.$
\end{theorem}
\begin{proof}[Proof sketch]
Case analysis: for nonzero reals $(-a)^{-1}=-(a^{-1})$; for $\pm\infty$ both
sides are $0$; for $\Phinull$ both sides are $\Phinull$.
\end{proof}

\begin{theorem}[Failure at zero: a signed-zero phenomenon]\label{thm:signedzero}
At $x=0$ the identity of Theorem~\ref{thm:recipneg} fails:
\[
\frac{1}{-0} = +\infty \qquad\text{while}\qquad -\frac{1}{0} = -\infty,
\]
and $+\infty\neq-\infty$.
\end{theorem}
\begin{proof}
Since $-0=0$, $1/(-0)=1/0=+\infty$. And $-(1/0)=-(+\infty)=-\infty$.
\end{proof}

The convention $1/0=+\infty$ tacitly treats the argument as a positive zero
$0^{+}$; a single sign-blind zero cannot support $1/(-x)=-(1/x)$ through it.
Restoring the law requires signed zeros $0^\pm$, as in floating-point.

\section{Order geometry: a total arithmetic with a non-total order}

\begin{definition}[Transreal order]
Let $\le$ be the reflexive relation with $\iota(a)\le\iota(b)$ iff $a\le b$,
$-\infty \le \iota(a) \le +\infty$ for all $a\in\R$, $-\infty\le+\infty$, and
$\Phinull\le\Phinull$ only. So $\Phinull$ is related to nothing but itself.
\end{definition}

\begin{theorem}[$\le$ is a partial order]\label{thm:po}
$\le$ is reflexive, antisymmetric, and transitive.
\end{theorem}
\begin{proof}[Proof sketch]
Reflexivity is built in; antisymmetry and transitivity are checked on the
six-way split, inherited from $(\R,\le)$ on the finite part, with the infinities
as strict bottom/top and $\Phinull$'s isolation making its clauses vacuous.
\end{proof}

\begin{theorem}[Not total]\label{thm:nottotal}
$\Phinull$ and $0$ are incomparable: neither $\Phinull\le 0$ nor $0\le\Phinull$.
\end{theorem}
\begin{proof}
$\Phinull$ is $\le$-related only to $\Phinull\neq 0$.
\end{proof}

\begin{theorem}[Order embedding of $\R$]\label{thm:oembed}
$a\le b$ in $\R$ iff $\iota(a)\le\iota(b)$ in $\T$.
\end{theorem}
\begin{proof}
Immediate from the finite clause.
\end{proof}

\begin{theorem}[No greatest and no least element]\label{thm:noextreme}
$\T$ has no greatest and no least element under $\le$.
\end{theorem}
\begin{proof}
If $g$ were greatest then $\Phinull\le g$, forcing $g=\Phinull$; but then
$0\le\Phinull$ is false, so $g$ is not an upper bound. The least-element case is
symmetric.
\end{proof}

\begin{contrast}[Versus the extended reals]
The extended real line $[-\infty,+\infty]$ is a complete lattice with greatest
$+\infty$ and least $-\infty$. Theorem~\ref{thm:noextreme} shows $\T$ is
categorically different: adjoining $\Phinull$ destroys the lattice extremes.
Totality of arithmetic is paid for with non-totality of order.
\end{contrast}

\section{Algorithms}

Totality makes transreal arithmetic executable without guards.

\paragraph{Total evaluation with a sticky nullity flag.}
\begin{verbatim}
function EVAL(expr):
    if expr is a constant c:  return TReal(c)
    if expr is (a OP b):
        x <- EVAL(a); y <- EVAL(b)
        return APPLY(OP, x, y)   # total; never raises
# Phi in output  <=>  some sub-evaluation was indeterminate (Phi absorbs).
\end{verbatim}

\paragraph{Double-reciprocal classifier.}
\begin{verbatim}
function DOUBLE_RECIP_IS_ID(x):
    return RECIP(RECIP(x)) == x    # True iff x != -inf  (Theorem 5.1)
\end{verbatim}

\paragraph{Three-valued comparison.}
\begin{verbatim}
function COMPARE(x, y):
    if x == Phi or y == Phi:
        return EQ if x == y else INCOMPARABLE
    return sign of (position(x) - position(y))   # -inf < R < +inf
\end{verbatim}

\section{Applications and discussion}

\textbf{Robust numerical pipelines.} No sub-expression can throw, and $\Phinull$
in the output is a sound and complete certificate that an indeterminate form
occurred---formalizing the role of \texttt{NaN} with cleaner laws (exact
commutativity and associativity of both operations).

\textbf{A dependency laboratory.} The transreals disentangle commutativity and
associativity (which survive) from inverses and distributivity (which fail), the
multiplicative involution (survives off one point), and total order (traded for
total arithmetic). Each law is attached to a named point.

\textbf{Relation to wheels.} Wheel theory gives a fully equational total-division
structure at the cost of extra identities and a bottom $\bot$. The transreals
satisfy weaker axioms; \S5 quantifies the gap, as the reciprocal deviates from
the wheel involution at exactly one point.

\textbf{Limitations.} $\T$ is not a ring, so linear algebra does not transfer
wholesale, and order-completeness arguments must be restricted to the
$\Phinull$-free part.

\section{Future directions}
\begin{itemize}[leftmargin=*]
  \item \textbf{Order/algebra interaction.} Whether the surviving monoid and
  order form an ordered commutative monoid on $\T\setminus\{\Phinull\}$; which
  covariance laws survive at $\pm\infty$; quotienting out $\Phinull$ to study
  $[-\infty,+\infty]$.
  \item \textbf{Analysis survival.} Transreal limits: IVT fails across
  $\Phinull$, but monotone-limit statements may survive on the $\Phinull$-free
  part.
  \item \textbf{Wheels and the projective line.} The single-point wheel
  $\R\cup\{\infty,\bot\}$ and the precise sense in which transreals sit below the
  wheel axioms.
  \item \textbf{Involution repair.} The largest sub-carrier on which the
  reciprocal is an involution (all but $-\infty$).
  \item \textbf{Linear algebra over $\T$.} What a ``transreal matrix product''
  can and cannot satisfy without distributivity.
\end{itemize}

\section{Conclusion}

Transreal arithmetic buys totality and this paper prices it exactly. The
surviving structure is a pair of commutative monoids joined by a negation
homomorphism and a faithful copy of the reals; the failures are the additive
inverse of $+\infty$, distributivity, the reciprocal involution at $-\infty$, the
reciprocal/negation law at $0$, and totality of the order. Each failure is
localized to a single named point, and everywhere else the classical law
survives.

\end{document}

