from dataclasses import dataclass
from typing import Optional

@dataclass(frozen=True)
class TReal:
    """A transreal number: kind in {'phi','pinf','ninf','rl'}; value set iff 'rl'."""
    kind: str
    value: Optional[float] = None
    def __repr__(self) -> str:
        return {"phi": "Phi", "pinf": "+inf", "ninf": "-inf"}.get(
            self.kind, f"{self.value:g}" if self.value is not None else "?")

PHI, PINF, NINF = TReal("phi"), TReal("pinf"), TReal("ninf")
def rl(x: float) -> TReal: return TReal("rl", float(x))
ZERO, ONE = rl(0.0), rl(1.0)

def add(x: TReal, y: TReal) -> TReal:
    if x.kind == "phi" or y.kind == "phi": return PHI
    if x.kind == "pinf": return PHI if y.kind == "ninf" else PINF
    if x.kind == "ninf": return PHI if y.kind == "pinf" else NINF
    if y.kind == "pinf": return PINF
    if y.kind == "ninf": return NINF
    return rl(x.value + y.value)

def _rti(a: float, pos: bool) -> TReal:
    if a == 0.0: return PHI
    return PINF if ((a > 0.0) == pos) else NINF

def mul(x: TReal, y: TReal) -> TReal:
    if x.kind == "phi" or y.kind == "phi": return PHI
    if x.kind in ("pinf","ninf") and y.kind in ("pinf","ninf"):
        return PINF if x.kind == y.kind else NINF
    if x.kind in ("pinf","ninf"): return _rti(y.value, x.kind == "pinf")
    if y.kind in ("pinf","ninf"): return _rti(x.value, y.kind == "pinf")
    return rl(x.value * y.value)

def neg(x: TReal) -> TReal:
    if x.kind == "phi": return PHI
    if x.kind == "pinf": return NINF
    if x.kind == "ninf": return PINF
    return rl(-x.value)

def recip(x: TReal) -> TReal:
    if x.kind == "phi": return PHI
    if x.kind in ("pinf","ninf"): return ZERO
    return PINF if x.value == 0.0 else rl(1.0 / x.value)

def main() -> None:
    print("1/0        =", recip(ZERO))
    print("0/0        =", mul(ZERO, recip(ZERO)))
    print("(+inf)+(-inf) =", add(PINF, NINF))
    print("0*(+inf)   =", mul(ZERO, PINF))
    print("1/(+inf)   =", recip(PINF))
    print("5 + Phi    =", add(rl(5), PHI), "  5 * Phi =", mul(rl(5), PHI))

if __name__ == "__main__":
