from typing import Tuple, Union

Expr = Union[float, Tuple]  # ('+',a,b) ('*',a,b) ('neg',a) ('recip',a)

def evaluate(e: Expr) -> TReal:
    if not isinstance(e, tuple):
        return rl(float(e))
